import * as T from 'three';
let seed=71933;
const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
function canvasTexture(draw,size=512){const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');draw(ctx,size);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;return t;}
export function makeMaterials(renderer){
 const wood=canvasTexture((ctx,s)=>{ctx.fillStyle='#c8b28e';ctx.fillRect(0,0,s,s);for(let k=0;k<8;k++){const y=k*s/8;ctx.fillStyle=`hsl(35,25%,${63+rand()*12}%)`;ctx.fillRect(0,y,s,s/8);for(let i=0;i<100;i++){ctx.strokeStyle=`rgba(${rand()>.5?'87,64,34':'246,227,187'},${.025+rand()*.11})`;ctx.lineWidth=.3+rand()*.8;ctx.beginPath();const yy=y+rand()*s/8;for(let x=0;x<=s;x+=8){const v=Math.sin(x/55+k*2+i)*.7+Math.sin(x/190+i)*2;if(x===0)ctx.moveTo(x,yy+v);else ctx.lineTo(x,yy+v);}ctx.stroke();}ctx.fillStyle='#8e806757';ctx.fillRect(0,y,s,1);const seam=(k%3)*s/3;ctx.fillRect(seam,y,1,s/8);}},1024);
 const walnut=canvasTexture((ctx,s)=>{ctx.fillStyle='#8a6b47';ctx.fillRect(0,0,s,s);for(let i=0;i<1600;i++){const x=rand()*s;ctx.strokeStyle=`rgba(42,25,10,${rand()*.14})`;ctx.beginPath();ctx.moveTo(x,0);ctx.bezierCurveTo(x+12*Math.sin(i),s*.3,x-9*Math.cos(i),s*.7,x,s);ctx.stroke();}},512);
 const fabric=canvasTexture((ctx,s)=>{ctx.fillStyle='#dfdbce';ctx.fillRect(0,0,s,s);for(let y=0;y<s;y+=3){ctx.strokeStyle=`rgba(70,67,53,${.03+rand()*.08})`;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(s,y);ctx.stroke();}for(let x=0;x<s;x+=3){ctx.fillStyle=`rgba(255,255,243,${.07+rand()*.12})`;ctx.fillRect(x,0,1,s);}for(let i=0;i<15000;i++){ctx.fillStyle=rand()>.5?'#fff8':'#6554';ctx.fillRect(rand()*s,rand()*s,1,1);}});
 const stone=canvasTexture((ctx,s)=>{ctx.fillStyle='#d8d9d2';ctx.fillRect(0,0,s,s);for(let i=0;i<10000;i++){const v=rand()>.5?255:90;ctx.fillStyle=`rgba(${v},${v},${v},${rand()*.1})`;ctx.fillRect(rand()*s,rand()*s,2,2);}for(let i=0;i<14;i++){ctx.strokeStyle='#878e7a16';ctx.lineWidth=.5+rand();ctx.beginPath();let yy=rand()*s;ctx.moveTo(0,yy);for(let x=0;x<s;x+=16){yy+=Math.sin(x/40+i)*3;ctx.lineTo(x,yy);}ctx.stroke();}ctx.strokeStyle='#a2a697';ctx.lineWidth=2;ctx.strokeRect(0,0,s,s);});
 const plaster=canvasTexture((ctx,s)=>{ctx.fillStyle='#edece4';ctx.fillRect(0,0,s,s);for(let i=0;i<32000;i++){ctx.fillStyle=rand()>.5?'#fff5':'#8c7c6c0b';ctx.fillRect(rand()*s,rand()*s,1,1);}});
 for(const map of [wood,walnut,fabric,stone,plaster])map.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());
 const std=(color,roughness=.6,metalness=0,extras={})=>new T.MeshStandardMaterial({color,roughness,metalness,...extras});
 const mats={wall:std('#f1eee5',.94,0,{map:plaster,bumpMap:plaster,bumpScale:.004}),trim:std('#eee9dd',.65),oak:std('#e1d1b5',.52,0,{map:wood}),walnut:std('#bba185',.48,0,{map:walnut}),fabric:std('#d2d4bd',.95,0,{map:fabric,bumpMap:fabric,bumpScale:.012}),linen:std('#eee8d9',.96,0,{map:fabric,bumpMap:fabric,bumpScale:.009}),green:std('#a0ad97',.95,0,{map:fabric,bumpMap:fabric,bumpScale:.007}),rug:std('#c7b99c',1,0,{map:fabric,bumpMap:fabric,bumpScale:.01}),stone:std('#e5e4da',.47,0,{map:stone,bumpMap:stone,bumpScale:.004}),tile:std('#dce0d8',.3,0,{map:stone}),ceramic:std('#faf9f0',.19),metal:std('#343e3b',.36,.65),brass:std('#ac9567',.35,.72),black:std('#272e2e',.52),white:std('#eeeee7',.5),leaf:std('#667d51',.85),soil:std('#574b39',1),leather:std('#707c73',.72),glass:new T.MeshPhysicalMaterial({color:'#dbe9e5',roughness:.08,metalness:0,transparent:true,opacity:.24,depthWrite:false,side:T.DoubleSide}),mirror:std('#b8c8c6',.06,.92),emissive:std('#fff0c8',.5,0,{emissive:'#ffd395',emissiveIntensity:0}),screen:std('#263c42',.25,.15,{emissive:'#547e88',emissiveIntensity:.12})};
 // Semantic tags survive cloning, including double-sided curtains and bedding.
 for(const [surface,material] of Object.entries(mats))material.userData.surface=surface;
 const floorMaterial=(w,d,kind='wood')=>{const tex=(kind==='tile'?stone:wood).clone();tex.needsUpdate=true;tex.repeat.set(kind==='tile'?w/0.6:w/2.4,kind==='tile'?d/0.6:d/2.4);return std('#ede1c6',.68,0,{map:tex,bumpMap:tex,bumpScale:.006});};
 return {mats,floorMaterial,std,fabric,wood,walnut};
}
